function saveSettings(){localStorage.setItem(SETTINGS_KEY,JSON.stringify(V70.settings))}
function resetComputerDeviceStats(){const marker='lameComputerStatsResetV92';if(localStorage.getItem(marker)==='1')return;try{const all=JSON.parse(localStorage.getItem('lamePersonalBestV65')||'{}')||{};for(const key of Object.keys(all))if(key.trim().toLowerCase()==='computer')delete all[key];localStorage.setItem('lamePersonalBestV65',JSON.stringify(all));localStorage.removeItem('lameComputerBrainV33');localStorage.setItem(marker,'1')}catch(e){}}
function xpLevel(xp){return Math.min(50,1+Math.floor(Math.sqrt(Math.max(0,xp)/250)))}
function xpFloor(lvl){return Math.pow(Math.max(0,lvl-1),2)*250}
function xpCeil(lvl){return Math.pow(lvl,2)*250}
function totalXp(){return Math.max(V70.localXp,Number(V70.progress&&V70.progress.xp)||0)}
function haptic(pattern){if(V70.settings.haptics&&navigator.vibrate)try{navigator.vibrate(pattern)}catch(e){}}
function esc70(v){return String(v==null?'':v).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
