 (controls||shell.firstChild).insertAdjacentElement(controls?'afterend':'beforebegin',bar);
 if(controls){const starMeter=document.createElement('div');starMeter.id='starPowerMeter';starMeter.className='starPowerMeter';starMeter.innerHTML='<div class="starPowerLabel"><span>⭐ STAR POWER ⭐</span><b id="starPowerPct">0%</b></div><div class="starPowerTrack"><div class="starPowerFill" id="starPowerFill"></div><div class="starPowerMarks">⭐ ⭐ ⭐ ⭐ ⭐</div></div>';controls.insertAdjacentElement('beforebegin',starMeter);const total=document.createElement('div');total.id='v73TotalPoints';total.className='v73TotalPoints';total.innerHTML='<span>TOTAL POINTS</span><b id="v73TotalPointsValue">0</b>';controls.insertAdjacentElement('afterend',total);const run=document.createElement('div');run.className='v92Stats';run.innerHTML='<div><b id="v92BossKills">0</b><span>BOSSES BEATEN</span></div><div><b id="v92FastBoss">—</b><span>FASTEST BOSS</span></div><div><b id="v92Missions">0</b><span>MISSIONS</span></div><div class="v92Challenge" id="v92Challenge">BONUS: REACH A x5 COMBO</div>';total.insertAdjacentElement('afterend',run)}
 const table=document.querySelector('.table');if(table){const reset=document.createElement('button');reset.id='resetGameBtn';reset.className='v96ResetGame';reset.hidden=true;reset.textContent='↻ RESET GAME';reset.setAttribute('aria-label','Reset the current game');table.appendChild(reset);const badge=document.createElement('div');badge.id='dailyModeBadge';badge.className='dailyModeBadge';badge.hidden=true;badge.textContent='📅 DAILY CHALLENGE';table.appendChild(badge);const boss=document.createElement('div');boss.id='bossHud';boss.className='bossHud';boss.innerHTML='<div class="bossLine"><span>🔒 FINAL BOX LOCK</span><span id="bossHpText">100 / 100</span></div><div class="bossTrack"><div class="bossFill" id="bossFill"></div></div>';table.appendChild(boss);const pb=document.createElement('div');pb.id='powerBadge';pb.className='powerBadge';table.appendChild(pb);const replay=document.createElement('div');replay.id='instantReplay';replay.className='instantReplay';replay.innerHTML='<span id="replayLabel">INSTANT REPLAY</span>';table.appendChild(replay)}
 document.body.insertAdjacentHTML('beforeend','<div class="powerToast" id="powerToast"></div><div class="bossExplosion" id="bossExplosion"><div>💥</div><b>BOX BOSS DESTROYED!</b></div><div class="boxLockOver hide" id="boxLockOver"><b>GAME OVER</b><strong>3,000,000 POINTS<br>LOCKS YOU IN THE BOX</strong><span>TRY AGAIN</span></div><div class="boxTimeoutOver hide" id="boxTimeoutOver"><b>GAME OVER</b><strong>YOU STAYED IN THE BOX<br>FOR TOO LONG</strong></div><div class="tutorialCard hide" id="tutorialCard"><h3 id="tutorialTitle"></h3><p id="tutorialText"></p><div class="tutorialActions"><button class="v70Button" id="tutorialSkip">SKIP</button><button class="v70Button" id="tutorialNext">NEXT</button></div></div>');
