 document.getElementById('pauseBtn').onclick=()=>openSettings();document.getElementById('dailyBtn').onclick=()=>openDaily();document.getElementById('resetGameBtn').onclick=()=>{if(!confirm('Reset this game and start over from Level 1?'))return;const computerMode=autoPlay;autoPlay=computerMode;if(computerMode)nicknameInput.value='Computer';else nicknameInput.value=localStorage.getItem('lameNicknameV11')||playerName||'';startGame();setStatus('↻ GAME RESET • LEVEL 1')};
 document.getElementById('settingsClose').onclick=closeSettings;document.getElementById('resumeBtn').onclick=closeSettings;
 document.getElementById('dailyClose').onclick=()=>hideOverlay('dailyOverlay');document.getElementById('dailyPlay').onclick=startDaily;document.getElementById('startBtn').addEventListener('click',()=>{if(!V70.startingDaily){V70.dailyMode=false;document.getElementById('dailyModeBadge').hidden=true}},true);
 const menu=document.querySelector('#startScreen .panel');if(menu&&!menu.classList.contains('v94Menu')){menu.classList.add('v94Menu');const intro=menu.querySelector('p');if(intro)intro.insertAdjacentHTML('afterend','<div class="v94MenuHero"><div class="v94BossLine">🤬 😱 🤢 🥶 👻</div><div class="v94Tagline">FREE HOWIE • DEFEAT THE BOSSES • OWN THE BOX</div><div class="v94Objectives"><div><b>100,000 PTS</b><span>FREE HOWIE • LEVEL 1</span></div><div><b>250,000 PTS</b><span>SUMMON BOSS • LEVEL 1</span></div></div></div>')}
 const howto=document.querySelector('.howto');if(howto)howto.insertAdjacentHTML('beforeend','<br><b>NEW LEVEL RULE:</b> Level 1 requires <b>100,000</b> points to free Howie, then <b>250,000 more</b> to summon the boss. Each new level adds <b>500 points</b> to both stages. Defeat the boss to advance.');
 document.getElementById('progressClose').onclick=()=>hideOverlay('progressOverlay');document.getElementById('shareClose').onclick=()=>hideOverlay('shareOverlay');
