function breakoutBossPosition(){const now=performance.now(),t=now/1000,large=level>=2,charging=V70.bossBattleStarted&&!V70.breakoutBoss&&!V70.levelBossDefeated,orbit={x:300+Math.sin(t*1.08)*(large?105:174),y:(large?365:430)+Math.sin(t*.73+1.4)*(large?65:135)};let target=charging?{x:W-118,y:cameraY+310}:orbit;if(!charging&&boxOpen===4&&V70.breakoutBoss){const h=getHowie(),current=V70.bossChasePos||orbit,d=Math.hypot(h.x-current.x,h.y-current.y);if(d>245)target={x:h.x+(current.x<h.x?-92:92),y:h.y-18}}if(!V70.bossChasePos)V70.bossChasePos={x:target.x,y:target.y,last:now};const pos=V70.bossChasePos,dt=Math.min(50,Math.max(0,now-(pos.last||now))),follow=charging?.006:(.0015+level*.00055),mix=Math.min(1,dt*follow);pos.x+=(target.x-pos.x)*mix;pos.y+=(target.y-pos.y)*mix;pos.last=now;const targetScale=charging?(large?.34:.72):1;V70.bossVisualScale=Number.isFinite(V70.bossVisualScale)?V70.bossVisualScale+(targetScale-V70.bossVisualScale)*.085:targetScale;return{x:pos.x,y:pos.y,r:(large?190:76)*V70.bossVisualScale,scale:V70.bossVisualScale,charging}}
function drawBreakoutBoss(){syncBreakoutBoss();if(!V70.breakoutBoss&&!(V70.bossBattleStarted&&!V70.levelBossDefeated))return;const p=breakoutBossPosition(),final=level===MAX_LEVEL,large=level>=2,pct=Math.max(0,Math.min(1,V70.breakoutBossHp/V70.breakoutBossMax)),pulse=.5+.5*Math.sin(performance.now()/80),meterY=large?190:84,attacking=performance.now()<V70.bossAttackUntil;ctx.save();ctx.translate(p.x,p.y);ctx.scale(p.scale,p.scale);ctx.textAlign='center';ctx.shadowBlur=30+22*pulse;ctx.shadowColor=level===3?'#46ff32':level===4?'#77e9ff':level===2?'#fff36a':pulse>.5?'#ff304c':'#ffffff';ctx.font=(large?'360':'120')+'px Arial';ctx.fillText(bossEmoji(attacking),0,large?115:38);if(!p.charging){ctx.shadowBlur=18;ctx.fillStyle='#fff';ctx.font='900 18px Impact,Arial Black,Arial';ctx.fillText(final?'LEVEL 5 GHOST BOSS':'LEVEL '+level+' '+(level===2?'SCREAM BOSS':level===3?'TOXIC BOSS':level===4?'FROZEN BOSS':'BOX BOSS'),0,meterY-12);ctx.fillStyle='rgba(0,0,0,.86)';ctx.fillRect(-116,meterY,232,43);ctx.fillStyle='#172635';ctx.fillRect(-110,meterY+6,220,13);ctx.fillStyle=pct>.5?'#51d9ff':'#ff304c';ctx.fillRect(-110,meterY+6,220*pct,13);ctx.fillStyle='#fff';ctx.font='900 16px Impact,Arial Black,Arial';ctx.fillText(Math.ceil(V70.breakoutBossHp).toLocaleString()+' HP',0,meterY+38)}ctx.restore()}
function updateBossAttack(){if(!V70.breakoutBoss||!V70.bossBattleStarted||V70.levelBossDefeated||boxOpen!==4||!playing||waiting||transitioning)return;const now=performance.now(),p=breakoutBossPosition(),h=getHowie(),distance=Math.hypot(h.x-p.x,h.y-p.y);if(distance>285||now-V70.bossAttackLast<850)return;V70.bossAttackLast=now;V70.bossAttackUntil=now+360;V70.howieBossHp=Math.max(0,V70.howieBossHp-50000);haptic([25,18,38]);sfxHit(1.9);const attack=level===2?'⚡ LIGHTNING STRIKE':level===3?'🤮 ULTRA GREEN BEAM':level===4?'🧊 FROZEN ICE ATTACK':'BOSS ATTACK';setStatus(bossEmoji(true)+' '+attack+' HIT HOWIE • '+V70.howieBossHp.toLocaleString()+' HOWIE HP LEFT');if(V70.howieBossHp<=0)retreatBossWithHowie()}
function drawBossAttackAndHowieHealth(){if(!V70.bossBattleStarted||V70.levelBossDefeated||!V70.breakoutBoss||boxOpen!==4)return;const now=performance.now(),p=breakoutBossPosition(),h=getHowie(),pct=Math.max(0,Math.min(1,V70.howieBossHp/1000000)),attacking=now<V70.bossAttackUntil;ctx.save();if(attacking){ctx.globalCompositeOperation='lighter';if(level===2){for(let bolt=0;bolt<3;bolt++){ctx.strokeStyle=bolt===1?'#fff':'#ffe928';ctx.shadowColor='#73cfff';ctx.shadowBlur=34;ctx.lineWidth=bolt===1?4:10;ctx.beginPath();ctx.moveTo(p.x,p.y);for(let i=1;i<7;i++){const q=i/7;ctx.lineTo(p.x+(h.x-p.x)*q+(Math.random()-.5)*34,p.y+(h.y-p.y)*q)}ctx.lineTo(h.x,h.y);ctx.stroke()}}else if(level===3){const g=ctx.createLinearGradient(p.x,p.y,h.x,h.y);g.addColorStop(0,'#efffff');g.addColorStop(.3,'#65ff35');g.addColorStop(1,'#00a817');ctx.strokeStyle=g;ctx.shadowColor='#4cff21';ctx.shadowBlur=45;ctx.lineWidth=28;ctx.beginPath();ctx.moveTo(p.x,p.y+18);ctx.lineTo(h.x,h.y);ctx.stroke();ctx.lineWidth=7;ctx.strokeStyle='#eaffb8';ctx.stroke()}else if(level===4){for(let i=0;i<9;i++){const q=((i/9)+(now%260)/260)%1,x=p.x+(h.x-p.x)*q,y=p.y+(h.y-p.y)*q;ctx.save();ctx.translate(x,y);ctx.rotate(now/90+i);ctx.shadowBlur=20;ctx.shadowColor='#8cecff';ctx.fillStyle=i%2?'#dffbff':'#78dfff';ctx.fillRect(-10,-10,20,20);ctx.strokeStyle='#fff';ctx.lineWidth=3;ctx.strokeRect(-10,-10,20,20);ctx.restore()}}else{ctx.strokeStyle='#ff304c';ctx.shadowColor='#ff304c';ctx.shadowBlur=28;ctx.lineWidth=9;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(h.x,h.y);ctx.stroke();ctx.strokeStyle='#fff';ctx.lineWidth=3;ctx.stroke()}}ctx.textAlign='center';ctx.fillStyle='rgba(0,0,0,.68)';ctx.fillRect(h.x-105,h.y-202,210,52);ctx.fillStyle='#32121a';ctx.fillRect(h.x-96,h.y-166,192,11);ctx.fillStyle=pct>.35?'#51d9ff':'#ff304c';ctx.fillRect(h.x-96,h.y-166,192*pct,11);ctx.fillStyle='#fff';ctx.font='900 15px Impact,Arial Black,Arial';ctx.fillText('HOWIE • '+Math.ceil(V70.howieBossHp).toLocaleString()+' HP',h.x,h.y-178);ctx.restore()}
function drawBossCornerHud(){if(!V70.bossBattleStarted||V70.levelBossDefeated)return;const charging=!V70.breakoutBoss,pct=Math.max(0,Math.min(1,V70.breakoutBossHp/V70.breakoutBossMax)),x=W-218,y=charging?112:18,pulse=.45+.55*Math.abs(Math.sin(performance.now()/145));ctx.save();ctx.fillStyle='rgba(0,0,0,.86)';ctx.strokeStyle=charging?'#ffd21f':'#ff304c';ctx.lineWidth=3;ctx.fillRect(x,y,200,charging?91:68);ctx.strokeRect(x,y,200,charging?91:68);ctx.fillStyle='#fff';ctx.font='900 14px Impact,Arial Black,Arial';ctx.textAlign='center';ctx.fillText(bossEmoji(false)+' BOSS HEALTH',x+100,y+20);ctx.fillStyle='#35121a';ctx.fillRect(x+10,y+30,180,12);ctx.fillStyle=pct>.5?'#ff304c':'#ff7b37';ctx.fillRect(x+10,y+30,180*pct,12);ctx.fillStyle='#fff';ctx.font='900 14px Impact,Arial Black,Arial';ctx.fillText(Math.ceil(V70.breakoutBossHp).toLocaleString()+' / '+V70.breakoutBossMax.toLocaleString(),x+100,y+59);if(charging){ctx.globalAlpha=pulse;ctx.shadowBlur=22;ctx.shadowColor='#ffd21f';ctx.fillStyle='#fff36a';ctx.font='900 16px Impact,Arial Black,Arial';ctx.fillText('⚡ CHARGING +'+Math.round(bossRegenRate()/1000)+'K HP/S ⚡',x+100,y+82)}ctx.restore()}
function howieStarAttackReady(){return V70.breakoutBoss&&V70.bossBattleStarted&&!V70.levelBossDefeated&&boxOpen===4&&playing&&!waiting&&!transitioning}
const STAR_CHARGE_MS=1800;
function starChargeAmount(now=performance.now()){return V70.starCharging?Math.max(0,Math.min(1,(now-(V70.starChargeStart||now))/STAR_CHARGE_MS)):0}
function beginStarCharge(){if(!howieStarAttackReady())return false;V70.starChargeHeld=true;if(!V70.starCharging){V70.starCharging=true;V70.starChargeStart=performance.now();tone(380,.1,'sine',.025,260);setStatus('⭐ HOLD TO BUILD STAR POWER!')}return true}
function cancelStarCharge(){V70.starCharging=false;V70.starChargeHeld=false;V70.starChargeStart=0;const fill=document.getElementById('starPowerFill'),pct=document.getElementById('starPowerPct');if(fill)fill.style.width='0%';if(pct)pct.textContent='0%'}
function releaseStarCharge(){if(!V70.starCharging)return;const now=performance.now(),power=starChargeAmount(now),recentFull=now-(V70.starChargeFiredAt||0)<260;V70.starChargeHeld=false;if(!recentFull)throwHowieStar(Math.max(.25,power));V70.starCharging=false;V70.starChargeStart=0}
function throwHowieStar(power=1){const now=performance.now(),p=Math.max(.25,Math.min(1,Number(power)||.25));if(!howieStarAttackReady()||now-V70.howieStarLast<320)return false;V70.howieStarLast=now;V70.howieThrowStart=now;V70.howieThrowUntil=now+520;const h=getHowie(),damage=Math.round(25000+75000*p);V70.howieStars.push({x:h.x+26,y:h.y-8,start:now,spin:Math.random()*6.28,power:p,scale:.75+p*.9,damage});if(V70.howieStars.length>12)V70.howieStars.shift();tone(880+p*720,.08,'triangle',.035+p*.025,420+p*220);haptic(p>=.98?[28,18,55]:18);setStatus(p>=.98?'🌟 FULL-POWER STAR FIRED!':'⭐ '+Math.round(p*100)+'% POWER STAR FIRED!');return true}
function updateStarCharge(){const ready=howieStarAttackReady(),meter=document.getElementById('starPowerMeter'),fill=document.getElementById('starPowerFill'),pct=document.getElementById('starPowerPct');if(meter)meter.classList.toggle('show',ready);if(!ready){cancelStarCharge();return}if(autoPlay&&!V70.starCharging)beginStarCharge();const p=starChargeAmount();if(fill)fill.style.width=Math.round(p*100)+'%';if(pct)pct.textContent=Math.round(p*100)+'%';if(V70.starCharging&&p>=1){throwHowieStar(1);V70.starChargeFiredAt=performance.now();if(V70.starChargeHeld){V70.starChargeStart=performance.now();if(fill)fill.style.width='0%'}else cancelStarCharge()}}
function drawStarChargeEffect(){if(!V70.starCharging||!howieStarAttackReady())return;const p=starChargeAmount(),h=getHowie(),pulse=.65+.35*Math.sin(performance.now()/55),size=30+p*74;ctx.save();ctx.translate(h.x+34,h.y-20);ctx.globalCompositeOperation='lighter';ctx.textAlign='center';ctx.textBaseline='middle';ctx.font=Math.round(size)+'px Arial';ctx.shadowBlur=18+p*52;ctx.shadowColor=p>.75?'#fff':'#ffd21f';ctx.globalAlpha=.72+.28*pulse;ctx.fillText('⭐',0,0);ctx.strokeStyle=p>.7?'#69e6ff':'#ffd21f';ctx.lineWidth=3+p*5;ctx.beginPath();ctx.arc(0,0,24+p*48,0,Math.PI*2*p);ctx.stroke();ctx.restore()}
function updateHowieStars(){const now=performance.now();for(let i=V70.howieStars.length-1;i>=0;i--){const s=V70.howieStars[i];if(!V70.breakoutBoss||V70.levelBossDefeated){V70.howieStars.splice(i,1);continue}const p=breakoutBossPosition(),dx=p.x-s.x,dy=p.y-s.y,d=Math.hypot(dx,dy)||1,step=Math.min(d,7.5+(s.power||.25)*4);s.x+=dx/d*step;s.y+=dy/d*step;s.spin+=.2+(s.power||.25)*.22;if(d<p.r+10*(s.scale||1)||now-s.start>2000){V70.howieStars.splice(i,1);const damage=s.damage||25000;V70.breakoutBossHp=Math.max(0,V70.breakoutBossHp-damage);showPointPopup(damage,p.x,p.y);score+=damage;updateHud();sfxHit(1.8+(s.power||.25));setStatus((s.power>=.98?'🌟 FULL STAR HIT! +':'⭐ STAR HIT! +')+damage.toLocaleString()+' • BOSS '+V70.breakoutBossHp.toLocaleString()+' HP');if(V70.breakoutBossHp<=0)destroyBreakoutBoss()}}}
function drawHowieStars(){ctx.save();ctx.textAlign='center';ctx.textBaseline='middle';for(const s of V70.howieStars){ctx.save();ctx.translate(s.x,s.y);ctx.rotate(s.spin);ctx.font=Math.round(42*(s.scale||1))+'px Arial';ctx.shadowBlur=20+30*(s.power||.25);ctx.shadowColor=s.power>=.75?'#ffffff':'#fff36a';ctx.globalAlpha=.82+.18*Math.sin(performance.now()/65);ctx.fillText('⭐',0,0);ctx.restore()}ctx.restore()}
function updateStarLaunchButton(){const b=document.getElementById('launchBtn');if(!b)return;const wasActive=b.classList.contains('howieStarAttack'),active=howieStarAttackReady();b.classList.toggle('howieStarAttack',active);if(active){const p=Math.round(starChargeAmount()*100);b.innerHTML=V70.starCharging?'⭐<br>'+p+'% POWER':'⭐<br>HOLD TO CHARGE';b.setAttribute('aria-label','Hold to charge Howie star power')}else{b.removeAttribute('aria-label');if(wasActive)b.innerHTML=inShooter?'HOLD<br>LAUNCH':extraBallsQueued>0?'LAUNCH<br>NEXT BALL':'MULTIBALL<br>ACTIVE'}}
function ballStuckOnLaunchPad(){return playing&&!waiting&&!transitioning&&!won&&!launchRailActive&&ball.x>490&&ball.y>930&&Math.hypot(ball.vx,ball.vy)<2.4}
function updateLaunchPadRescue(){if(howieStarAttackReady())return;const b=document.getElementById('launchBtn');if(!b)return;const wasRescue=b.classList.contains('launchRescue');if(ballStuckOnLaunchPad()){b.classList.add('launchRescue');b.innerHTML='🚀<br>RE-LAUNCH'}else{b.classList.remove('launchRescue');if(wasRescue)b.innerHTML=inShooter?'HOLD<br>LAUNCH':extraBallsQueued>0?'LAUNCH<br>NEXT BALL':'MULTIBALL<br>ACTIVE'}}
async function triggerBoxLockGameOver(){if(V70.boxLockGameOver||V70.boxTimeoutGameOver||boxOpen===4||breakoutRemaining()<3000000)return;V70.boxLockGameOver=true;playing=false;waiting=true;V70.breakoutBoss=false;V70.howieStars=[];stopHipHopBeat();playGameOverSong();const over=document.getElementById('boxLockOver');over.classList.remove('hide');haptic([100,50,140,50,220]);setTimeout(async()=>{over.classList.add('hide');await finishRecord();renderGameOver();const result=document.getElementById('finalScore');if(result)result.insertAdjacentHTML('afterbegin','<div class="boxLockResult">🔒 3,000,000-POINT BOX LOCK</div>');document.getElementById('gameOver').classList.remove('hide')},2600)}
function updateHowieBoxCountdown(){const eligible=V70.bossBattleStarted&&!V70.levelBossDefeated&&!V70.bossSequenceRunning&&boxOpen<4&&!V70.boxLockGameOver&&!V70.boxTimeoutGameOver;if(!eligible){V70.howieBoxTimerActive=false;V70.howieBoxTimerRemaining=120000;V70.howieBoxTimerLast=0;return}const now=performance.now();if(!V70.howieBoxTimerActive){V70.howieBoxTimerActive=true;V70.howieBoxTimerRemaining=120000;V70.howieBoxTimerLast=now;showPowerToast('⏱️ 2:00 BOX TIMER','GET HOWIE OUT BEFORE TIME EXPIRES');return}const dt=Math.min(250,now-V70.howieBoxTimerLast);V70.howieBoxTimerLast=now;if(playing)V70.howieBoxTimerRemaining=Math.max(0,V70.howieBoxTimerRemaining-dt);if(V70.howieBoxTimerRemaining<=0)triggerHowieBoxTimeout()}
function drawHowieBoxCountdown(){if(!V70.howieBoxTimerActive||boxOpen===4||V70.boxTimeoutGameOver)return;const sec=Math.ceil(V70.howieBoxTimerRemaining/1000),text=Math.floor(sec/60)+':'+String(sec%60).padStart(2,'0'),color=boxNumberColor();ctx.save();ctx.textAlign='center';ctx.shadowBlur=26;ctx.shadowColor=color;ctx.fillStyle=color;ctx.font='900 32px Impact,Arial Black,Arial';ctx.fillText(text,300,760);ctx.font='900 10px Impact,Arial Black,Arial';ctx.fillText('GET HOWIE OUT BEFORE TIME EXPIRES',300,778);ctx.restore()}
function enforceNoSlowBall(b,main=false){if(!b||!playing||waiting||transitioning||won||(main&&(inShooter||launchRailActive||holeCapture||trickMode))||(!main&&b.inShooter))return;const speed=Math.hypot(b.vx,b.vy),minimum=5.25+level*.3;if(speed>=minimum)return;if(speed>.08){const scale=minimum/speed;b.vx*=scale;b.vy*=scale}else{b.vx=(b.x<300?1:-1)*minimum*.55;b.vy=-minimum*.84}}
async function triggerHowieBoxTimeout(){if(V70.boxTimeoutGameOver||V70.boxLockGameOver)return;V70.boxTimeoutGameOver=true;playing=false;waiting=true;V70.breakoutBoss=false;V70.howieStars=[];stopHipHopBeat();playGameOverSong();const over=document.getElementById('boxTimeoutOver');over.classList.remove('hide');haptic([120,60,180,60,260]);setTimeout(async()=>{over.classList.add('hide');await finishRecord();renderGameOver();const result=document.getElementById('finalScore');if(result)result.insertAdjacentHTML('afterbegin','<div class="boxLockResult">⏱️ BOX TIME EXPIRED</div>');document.getElementById('gameOver').classList.remove('hide')},3000)}
function collideBreakoutBossFor(b){syncBreakoutBoss();if(!V70.breakoutBoss||!playing||waiting||(b===ball?inShooter:b.inShooter))return;const p=breakoutBossPosition(),dx=b.x-p.x,dy=b.y-p.y,d=Math.hypot(dx,dy),min=(b.r||13)+p.r;if(d>=min)return;const nx=dx/(d||1),ny=dy/(d||1),dot=b.vx*nx+b.vy*ny;if(dot<0){b.vx-=2.2*dot*nx;b.vy-=2.2*dot*ny}b.x=p.x+nx*(min+2);b.y=p.y+ny*(min+2);const now=performance.now();if(now-V70.breakoutBossLastHit<150)return;V70.breakoutBossLastHit=now;V70.breakoutBossHp=Math.max(0,V70.breakoutBossHp-40000);score+=40000;showPointPopup(40000,p.x,p.y);updateHud();haptic([38,18,48]);sfxHit(2.4);setStatus('🤬 BOX BOSS HIT! +40,000 • '+V70.breakoutBossHp.toLocaleString()+' HP LEFT');if(V70.breakoutBossHp<=0)destroyBreakoutBoss()}
function drawLargeHowieCounter(){if(boxOpen!==4)return;const h=getHowie(),color=boxNumberColor();ctx.save();ctx.textAlign='center';ctx.shadowBlur=22;ctx.shadowColor='#000';ctx.fillStyle='#fff';ctx.font='900 15px Impact,Arial Black,Arial';ctx.fillText('TOTAL GAME POINTS',h.x,h.y+100);ctx.shadowColor=color;ctx.fillStyle=color;ctx.font='900 31px Impact,Arial Black,Arial';ctx.fillText(Math.floor(score).toLocaleString(),h.x,h.y+136);ctx.shadowColor='#000';ctx.fillStyle='#fff';ctx.font='900 15px Impact,Arial Black,Arial';ctx.fillText('POINTS WHILE HOWIE IS OUT',h.x,h.y+182);ctx.shadowColor=color;ctx.fillStyle=color;ctx.font='900 31px Impact,Arial Black,Arial';ctx.fillText(Math.floor(howieOutPointsShown).toLocaleString(),h.x,h.y+221);ctx.restore()}
function updateBreakoutLabel(){const el=document.querySelector('.boxTitle span:last-child');if(el)el.textContent='TOTAL BREAKOUT '+totalBreakoutCost().toLocaleString()+' PTS • +5,000 EACH LOST BALL'}
function registerBallLoss(){V70.lostBalls++;V70.breakoutMultiplier=V70.lostBalls+1;const battle=V70.bossBattleStarted&&!V70.levelBossDefeated,step=breakoutStep(),total=totalBreakoutCost();boxOpen=0;nextFlapScore=score+step;if(battle){cancelStarCharge();V70.breakoutBoss=false;V70.bossRetreatAt=performance.now();V70.bossRegenLast=V70.bossRetreatAt}updateFlaps();updateBreakoutLabel();setStatus('BALL LOST • HOWIE IS BACK IN THE BOX • '+total.toLocaleString()+' POINTS TO BREAK OUT');showPowerToast('HOWIE IS BACK IN THE BOX','GET-OUT POINTS INCREASED BY 5,000 • '+total.toLocaleString()+' TOTAL')}
function applyMegaScoreBonus(){const delta=Math.max(0,score-V70.megaScoreCheckpoint);if(V70.activePower==='mega'&&performance.now()<V70.powerEnds&&delta>0){const bonus=delta*9;score+=bonus;if(boxOpen===4)howieOutPoints+=bonus;showPointPopup(bonus,ball.x,ball.y);updateHud();openFlapsAndLevels();setStatus('🌕 10× MEGA POINTS! +'+bonus.toLocaleString())}V70.megaScoreCheckpoint=score}
function captureReplayFrame(){if(V70.replay||!playing||waiting)return;V70.replayFrames.push({x:ball.x,y:ball.y,cameraY,t:performance.now()});if(V70.replayFrames.length>75)V70.replayFrames.shift()}
function startInstantReplay(label){if(V70.replay||V70.replayFrames.length<18||transitioning||won)return;const was=playing;playing=false;V70.replay={label,frames:V70.replayFrames.slice(-55),start:performance.now(),was};document.getElementById('replayLabel').textContent='⏪ '+label;document.getElementById('instantReplay').classList.add('show');setTimeout(()=>{document.getElementById('instantReplay').classList.remove('show');const r=V70.replay;V70.replay=null;if(r&&r.was&&!V70.paused&&!won&&!transitioning)playing=true},1450)}
function drawReplayGhost(){if(!V70.replay)return;const r=V70.replay,p=Math.min(1,(performance.now()-r.start)/1300),i=Math.min(r.frames.length-1,Math.floor(p*r.frames.length)),f=r.frames[i];ctx.save();ctx.globalAlpha=.75;ctx.shadowBlur=28;ctx.shadowColor='#ffd21f';ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(f.x,f.y-f.cameraY,18,0,Math.PI*2);ctx.fill();ctx.restore()}
const tutorialSteps=[
 {title:'LAUNCH THE BALL',text:'Hold LAUNCH to build momentum, then release. You can relaunch any ball stuck in the launch lane.',target:'#launchBtn'},
 {title:'CONTROL THE FLIPPERS',text:'Use LEFT and RIGHT to keep the ball alive. Keyboard players can use A/D or the arrow keys.',target:'.controls'},
 {title:'FREE HOWIE',text:'Score points to open all four box flaps. When Howie gets out, every point is doubled.',target:'.boxStatus'},
 {title:'GRAB POWER-UPS',text:'Hit glowing power-up icons for Ball Save, Triple Points, Magnet Ball, Giant Ball or the 20-second 5× Mega Ball.',target:'.table'},
 {title:'CLIMB AND SHARE',text:'Earn XP, unlock visual rewards, play the Daily Challenge and share your result card.',target:'.v70TopBar'}
];
function formatRunTime(ms){if(!Number.isFinite(ms)||ms<=0)return '—';const s=Math.max(0,ms/1000);return s<60?s.toFixed(1)+'s':Math.floor(s/60)+':'+String(Math.floor(s%60)).padStart(2,'0')}
function frameGameplay(){setTimeout(()=>{const table=document.querySelector('.table');if(table)table.scrollIntoView({behavior:'smooth',block:'start'});cameraY=400},140)}
function playGameOverSong(){initAudio();const notes=[220,196,174.6,146.8,110,82.4];notes.forEach((n,i)=>{tone(n,.34,i%2?'triangle':'sawtooth',.055,-n*.28,i*.19);if(i%2===0)noise(.08,.018,i*.19)});setTimeout(()=>tone(55,.85,'sine',.07,-12),980)}
function playVictorySong(){initAudio();const melody=[261.6,329.6,392,523.3,659.3,784,1046.5];melody.forEach((n,i)=>{tone(n,.28,i%2?'triangle':'square',.05,n*.08,i*.16);tone(n/2,.34,'sine',.025,0,i*.16)});setTimeout(()=>{[523.3,659.3,784].forEach(n=>tone(n,.75,'triangle',.035,n*.05))},1200)}
function updateRunStatsPanel(){const kills=document.getElementById('v92BossKills'),fast=document.getElementById('v92FastBoss'),missions=document.getElementById('v92Missions'),challenge=document.getElementById('v92Challenge');if(kills)kills.textContent=String(V70.bossKills||0);if(fast)fast.textContent=formatRunTime(V70.fastestBossMs);if(missions)missions.textContent=String(missionDoneLevels?.size||0);if(!challenge)return;const t=Math.floor((performance.now()-(V70.runStartedAt||performance.now()))/1000);if(level===1)challenge.textContent='BONUS: REACH x5 COMBO • '+Math.min(5,V70.maxCombo||1)+'/5';else if(level===2)challenge.textContent='BONUS: HIT 20 BUMPERS • '+Math.min(20,V70.bumperHits||0)+'/20';else if(level===3)challenge.textContent='BONUS: KEEP HOWIE OUT 30s • '+Math.min(30,Math.floor(outMs()/1000))+'/30';else if(level===4)challenge.textContent='BONUS: DEFEAT THE BOSS IN UNDER 60s • BEST '+formatRunTime(V70.fastestBossMs);else challenge.textContent='FINAL BONUS: WIN THE GAME • PLAY TIME '+formatRunTime(t*1000)}
function startTutorial(){if(!V70.settings.tutorial||localStorage.getItem(TUTORIAL_KEY)==='1')return;V70.tutorialActive=true;V70.tutorialStep=0;showTutorialStep()}
function clearTutorialTarget(){document.querySelectorAll('.tutorialPulse').forEach(e=>e.classList.remove('tutorialPulse'))}
function showTutorialStep(){const s=tutorialSteps[V70.tutorialStep],card=document.getElementById('tutorialCard');clearTutorialTarget();document.getElementById('tutorialTitle').textContent=(V70.tutorialStep+1)+' / '+tutorialSteps.length+' • '+s.title;document.getElementById('tutorialText').textContent=s.text;document.getElementById('tutorialNext').textContent=V70.tutorialStep===tutorialSteps.length-1?'FINISH':'NEXT';card.classList.remove('hide');document.querySelector(s.target)?.classList.add('tutorialPulse')}
